def _iso_min(d):
    m=re.fullmatch(r'PT(?:(\d+)H)?(?:(\d+)M)?',d);return int(m.group(1) or 0)*60+int(m.group(2) or 0)
def _ld(items):return ''.join('<script type="application/ld+json">'+json.dumps(x,ensure_ascii=False)+'</script>' for x in items)
